/**
 * One typed progress event.
 *
 * Variants cover the run lifecycle. Eval, refine, provider and renderer events stay
 * [`ProgressEvent::Other`] until the generation slice needs them — a front-end can already
 * key on the name without this enum pretending to model what it has not been tested against.
 */

public enum ProgressEvent: Equatable, Hashable {
    
    case runStarted(totalOutputs: UInt64, totalPrompts: UInt64, variantCount: UInt64, dryRun: Bool
    )
    case planItem(promptId: String, assetType: String, service: String, model: String, outputPath: String
    )
    case outputStarted(promptId: String, index: UInt64, total: UInt64, outputPath: String
    )
    case outputCompleted(promptId: String, outputPath: String, ok: Bool, service: String, 
        /**
         * `None` where the library emitted the `NO_SCORE` sentinel — the `-1.0` never leaks.
         */score: Double?
    )
    case attemptStarted(promptId: String, attempt: UInt64, totalAttempts: UInt64, service: String, model: String, outputPath: String
    )
    case attemptCompleted(promptId: String, attempt: UInt64, service: String, outputPath: String, ok: Bool, 
        /**
         * `None` where the library emitted the `NO_SCORE` sentinel.
         */score: Double?
    )
    case attemptFailed(promptId: String, attempt: UInt64, service: String, outputPath: String, reason: String
    )
    case runCompleted(succeeded: UInt64, failed: UInt64, dryRun: Bool
    )
    /**
     * A progress event this slice does not model yet. Carries its taxonomy name only.
     */
    case other(event: String
    )





}

